from collections.abc import Generator, Iterable
from xml.etree.ElementTree import Element

from pdf_craft.transformer.xml_translator.xml import clone_element
from .parser import parse_tags
from .tag import Tag, TagKind
from .transform import tag_to_element


# why implement XML decoding?
# https://github.com/oomol-lab/pdf-craft/issues/149
def decode_friendly(chars: Iterable[str], tags: Iterable[str] | str = ()) -> Generator[Element, None, None]:
    if isinstance(tags, str):
        tags = set((tags,))
    else:
        tags = set(tags)

    for element in _collect_elements(chars):
        if element.tag in tags or len(tags) == 0:
            yield clone_element(element)


def _collect_elements(chars: Iterable[str]) -> Generator[Element, None, None]:
    opening_stack: list[Element] = []
    last_closed_element: Element | None = None

    for cell in parse_tags(chars):
        if isinstance(cell, Tag):
            tag: Tag = cell
            element = tag_to_element(tag)
            if tag.kind == TagKind.CLOSING:
                popped = _pop_element(tag.name, opening_stack)
                if popped is not None:
                    yield popped
                    last_closed_element = popped
                elif last_closed_element is not None:
                    _append_to_tail(last_closed_element, tag.proto)
            else:
                if opening_stack:
                    opening_stack[-1].append(element)
                if tag.kind == TagKind.SELF_CLOSING:
                    yield element
                    last_closed_element = element
                elif tag.kind == TagKind.OPENING:
                    opening_stack.append(element)
                    last_closed_element = None

        elif last_closed_element is not None:
            _append_to_tail(last_closed_element, cell)

        elif opening_stack:
            opening_stack[-1].text = cell


def _append_to_tail(element: Element, text: str) -> None:
    if element.tail:
        element.tail += text
    else:
        element.tail = text


def _pop_element(tag_name: str, opening_stack: list[Element]) -> Element | None:
    index = -1
    for i in range(len(opening_stack) - 1, -1, -1):
        opening_element = opening_stack[i]
        if tag_name == opening_element.tag:
            index = i
            break
    if index == -1:
        return None

    popped: Element | None = None
    for _ in range(len(opening_stack) - index):
        popped = opening_stack.pop()
    return popped

from collections.abc import Callable, Generator, Iterable, Iterator
from typing import TypeVar
from xml.etree.ElementTree import Element

from resource_segmentation import Group, Resource, Segment, split
from tiktoken import Encoding

from pdf_craft.transformer.xml_translator.segment import InlineSegment, TextSegment, search_inline_segments, search_text_segments
from .callbacks import Callbacks
from .concurrency import run_concurrency
from .score import ScoreSegment, expand_to_score_segments, truncate_score_segment

_PAGE_INCISION = 0
_BLOCK_INCISION = 1
_T = TypeVar("_T")

_ResourcePayload = tuple[InlineSegment, list[ScoreSegment]]


InlineSegmentMapping = tuple[Element, list[TextSegment]]
InlineSegmentGroupMap = Callable[[list[InlineSegment]], list[InlineSegmentMapping | None]]


class XMLStreamMapper:
    def __init__(self, encoding: Encoding, max_group_score: int) -> None:
        self._encoding: Encoding = encoding
        self._max_group_score: int = max_group_score

    def map_stream(
        self,
        elements: Iterator[Element],
        callbacks: Callbacks,
        map: InlineSegmentGroupMap,
        concurrency: int,
    ) -> Generator[tuple[Element, list[InlineSegmentMapping]], None, None]:
        current_element: Element | None = None
        mapping_buffer: list[InlineSegmentMapping] = []

        def execute(group: Group[_ResourcePayload]):
            head, body, tail = self._truncate_and_transform_group(group)
            head = [segment.clone() for segment in head]
            tail = [segment.clone() for segment in tail]
            target_body = map(head + body + tail)[len(head) : len(head) + len(body)]
            return zip(body, target_body, strict=False)

        for mapping_pairs in run_concurrency(
            parameters=self._split_into_serial_groups(elements, callbacks),
            execute=execute,
            concurrency=concurrency,
        ):
            for origin, target in mapping_pairs:
                origin_element = origin.head.root
                if current_element is None:
                    current_element = origin_element

                if id(current_element) != id(origin_element):
                    yield current_element, mapping_buffer
                    current_element = origin_element
                    mapping_buffer = []

                if target:
                    block_element, text_segments = target
                    block_element = callbacks.interrupt_block_element(block_element)
                    text_segments = list(callbacks.interrupt_translated_text_segments(text_segments))
                    if text_segments:
                        mapping_buffer.append((block_element, text_segments))

        if current_element is not None:
            yield current_element, mapping_buffer

    def _split_into_serial_groups(self, elements: Iterable[Element], callbacks: Callbacks):
        def generate():
            for element in elements:
                yield from split(
                    max_segment_count=self._max_group_score,
                    border_incision=_PAGE_INCISION,
                    resources=self._expand_to_resources(element, callbacks),
                )

        generator = generate()
        group = next(generator, None)
        if group is None:
            return

        # head + body * N (without tail)
        sum_count = group.head_remain_count + sum(x.count for x in self._expand_resource_segments(group.body))

        while True:
            next_group = next(generator, None)
            if next_group is None:
                break

            next_sum_body_count = sum(x.count for x in self._expand_resource_segments(next_group.body))
            next_sum_count = sum_count + next_sum_body_count

            if next_sum_count + next_group.tail_remain_count > self._max_group_score:
                yield group
                group = next_group
                sum_count = group.head_remain_count + next_sum_body_count
            else:
                group.body.extend(next_group.body)
                group.tail = next_group.tail
                group.tail_remain_count = next_group.tail_remain_count
                sum_count = next_sum_count

        yield group

    def _truncate_and_transform_group(
        self, group: Group[_ResourcePayload]
    ) -> tuple[list[InlineSegment], list[InlineSegment], list[InlineSegment]]:
        head = self._truncate_group_gap(
            gap=group.head,
            remain_head=False,
            remain_score=group.head_remain_count,
        )
        body = self._expand_inline_segments(group.body)
        tail = self._truncate_group_gap(
            gap=group.tail,
            remain_head=True,
            remain_score=group.tail_remain_count,
        )
        return (
            [r.payload[0] for r in head],
            [p[0] for p in body],
            [r.payload[0] for r in tail],
        )

    def _expand_to_resources(self, element: Element, callbacks: Callbacks):
        def expand(element: Element):
            text_segments = search_text_segments(element)
            text_segments = callbacks.interrupt_source_text_segments(text_segments)
            yield from search_inline_segments(text_segments)

        inline_segment_generator = expand(element)
        start_incision = _PAGE_INCISION
        inline_segment = next(inline_segment_generator, None)
        if inline_segment is None:
            return

        while True:
            next_inline_segment = next(inline_segment_generator, None)
            if next_inline_segment is None:
                break

            if next_inline_segment.head.root is inline_segment.tail.root:
                end_incision = _BLOCK_INCISION
            else:
                end_incision = _PAGE_INCISION

            yield self._transform_to_resource(
                inline_segment=inline_segment,
                start_incision=start_incision,
                end_incision=end_incision,
            )
            inline_segment = next_inline_segment
            start_incision = end_incision

        yield self._transform_to_resource(
            inline_segment=inline_segment,
            start_incision=start_incision,
            end_incision=_PAGE_INCISION,
        )

    def _transform_to_resource(
        self,
        inline_segment: InlineSegment,
        start_incision: int,
        end_incision: int,
    ) -> Resource[_ResourcePayload]:
        source_segments = list(
            expand_to_score_segments(
                encoding=self._encoding,
                inline_segment=inline_segment,
            )
        )
        return Resource(
            count=sum(segment.score for segment in source_segments),
            start_incision=start_incision,
            end_incision=end_incision,
            payload=(inline_segment, source_segments),
        )

    def _expand_inline_segments(self, items: list[Resource[_ResourcePayload] | Segment[_ResourcePayload]]):
        for resource in self._expand_resource_segments(items):
            yield resource.payload

    def _expand_resource_segments(self, items: list[Resource[_ResourcePayload] | Segment[_ResourcePayload]]):
        for item in items:
            if isinstance(item, Resource):
                yield item
            elif isinstance(item, Segment):
                yield from item.resources

    def _truncate_group_gap(
        self,
        gap: list[Resource[_ResourcePayload] | Segment[_ResourcePayload]],
        remain_head: bool,
        remain_score: int,
    ):
        def expand_resource_segments(items: list[Resource[_ResourcePayload] | Segment[_ResourcePayload]]):
            for item in items:
                if isinstance(item, Resource):
                    yield item
                elif isinstance(item, Segment):
                    yield from item.resources

        resources, remain_score = _truncate_items(
            items=expand_resource_segments(gap),
            score=lambda resource: resource.count,
            remain_head=remain_head,
            remain_score=remain_score,
        )
        if remain_score > 0:
            resource = resources.pop() if remain_head else resources.pop(0)
            inline_segment, score_segments = resource.payload
            score_segments, remain_score = _truncate_items(
                items=score_segments,
                score=lambda score_segment: score_segment.score,
                remain_head=remain_head,
                remain_score=remain_score,
            )
            if remain_score > 0:
                score_segment = score_segments.pop() if remain_head else score_segments.pop(0)
                score_segment = truncate_score_segment(
                    score_segment=score_segment,
                    encoding=self._encoding,
                    remain_head=remain_head,
                    remain_score=remain_score,
                )
                if score_segment is not None:
                    if remain_head:
                        score_segments.append(score_segment)
                    else:
                        score_segments.insert(0, score_segment)

                inline_segment = next(
                    search_inline_segments(s.text_segment for s in score_segments),
                    None,
                )

            if inline_segment is not None:
                resource = Resource(
                    count=sum(s.score for s in score_segments),
                    start_incision=resource.start_incision,
                    end_incision=resource.end_incision,
                    payload=(inline_segment, score_segments),
                )
                if remain_head:
                    resources.append(resource)
                else:
                    resources.insert(0, resource)

        return resources


def _truncate_items(items: Iterable[_T], score: Callable[[_T], int], remain_head: bool, remain_score: int):
    truncated_items = list(items)
    if not truncated_items:
        return truncated_items, 0

    if not remain_head:
        truncated_items.reverse()

    truncated_index: int | None = None
    for i, item in enumerate(truncated_items):
        item_score = score(item)
        remain_score -= item_score
        if remain_score <= 0:
            truncated_index = i
            break

    if truncated_index is not None:
        while len(truncated_items) > truncated_index + 1:
            truncated_items.pop()

    if truncated_items and remain_score < 0:
        remain_score = score(truncated_items[-1]) + remain_score
    else:
        remain_score = 0

    if not remain_head:
        truncated_items.reverse()

    return truncated_items, remain_score

from collections.abc import Generator, Iterable
from enum import Enum, auto
from io import StringIO

from .tag import Tag, TagKind, is_valid_name_char, is_valid_value_char

_SPACES = (" ", "\n")


class _Phase(Enum):
    OUTSIDE = auto()
    LEFT_BRACKET = auto()
    LEFT_SLASH = auto()
    TAG_NAME = auto()
    TAG_GAP = auto()
    ATTRIBUTE_NAME = auto()
    ATTRIBUTE_NAME_EQUAL = auto()
    ATTRIBUTE_VALUE = auto()
    MUST_CLOSING_SIGN = auto()


class _ParsedResult(Enum):
    Continue = auto()
    Success = auto()
    Failed = auto()


def parse_tags(chars: Iterable[str]) -> Generator[str | Tag, None, None]:
    yield from _XMLTagsParser().do(chars)


class _XMLTagsParser:
    def __init__(self):
        self._outside_buffer: StringIO = StringIO()
        self._tag_buffer: StringIO = StringIO()
        self._tag: Tag | None = None
        self._phase: _Phase = _Phase.OUTSIDE

    def do(self, chars: Iterable[str]) -> Generator[str | Tag, None, None]:
        for char in chars:
            parsed_result = self._parse_char(char)
            yield from self._generate_by_result(parsed_result)

        self._outside_buffer.write(self._tag_buffer.getvalue())
        outside_text = self._outside_buffer.getvalue()
        if outside_text != "":
            yield outside_text

    def _parse_char(self, char: str) -> _ParsedResult:
        parsed_result: _ParsedResult = _ParsedResult.Continue

        if self._phase == _Phase.OUTSIDE:
            if char != "<":
                self._outside_buffer.write(char)
            else:
                self._phase = _Phase.LEFT_BRACKET
                self._tag_buffer.write(char)
                self._tag = Tag(
                    kind=TagKind.OPENING,
                    name="",
                    proto="",
                    attributes=[],
                )
        else:
            assert self._tag is not None
            self._tag_buffer.write(char)

            if self._phase == _Phase.LEFT_BRACKET:
                if char == "/":
                    self._tag.kind = TagKind.CLOSING
                    self._phase = _Phase.LEFT_SLASH
                elif is_valid_name_char(char):
                    self._tag.name += char
                    self._phase = _Phase.TAG_NAME
                else:
                    parsed_result = _ParsedResult.Failed

            elif self._phase == _Phase.LEFT_SLASH:
                if is_valid_name_char(char):
                    self._tag.name += char
                    self._phase = _Phase.TAG_NAME
                else:
                    parsed_result = _ParsedResult.Failed

            elif self._phase == _Phase.TAG_NAME:
                if char in _SPACES:
                    self._phase = _Phase.TAG_GAP
                elif is_valid_name_char(char):
                    self._tag.name += char
                elif char == ">":
                    parsed_result = _ParsedResult.Success
                elif char == "/" and self._tag.kind == TagKind.OPENING:
                    self._tag.kind = TagKind.SELF_CLOSING
                    self._phase = _Phase.MUST_CLOSING_SIGN
                else:
                    parsed_result = _ParsedResult.Failed

            elif self._phase == _Phase.TAG_GAP:
                if char in _SPACES:
                    pass
                elif is_valid_name_char(char):
                    self._tag.attributes.append((char, ""))
                    self._phase = _Phase.ATTRIBUTE_NAME
                elif char == ">":
                    parsed_result = _ParsedResult.Success
                elif char == "/" and self._tag.kind == TagKind.OPENING:
                    self._tag.kind = TagKind.SELF_CLOSING
                    self._phase = _Phase.MUST_CLOSING_SIGN
                else:
                    parsed_result = _ParsedResult.Failed

            elif self._phase == _Phase.ATTRIBUTE_NAME:
                if is_valid_name_char(char):
                    attr_name, attr_value = self._tag.attributes[-1]
                    attr_name = attr_name + char
                    self._tag.attributes[-1] = (attr_name, attr_value)
                elif char == "=":
                    self._phase = _Phase.ATTRIBUTE_NAME_EQUAL
                else:
                    parsed_result = _ParsedResult.Failed

            elif self._phase == _Phase.ATTRIBUTE_NAME_EQUAL:
                if char == '"':
                    self._phase = _Phase.ATTRIBUTE_VALUE
                else:
                    parsed_result = _ParsedResult.Failed

            elif self._phase == _Phase.ATTRIBUTE_VALUE:
                if is_valid_value_char(char):
                    attr_name, attr_value = self._tag.attributes[-1]
                    attr_value = attr_value + char
                    self._tag.attributes[-1] = (attr_name, attr_value)
                elif char == '"':
                    self._phase = _Phase.TAG_GAP
                else:
                    parsed_result = _ParsedResult.Failed

            elif self._phase == _Phase.MUST_CLOSING_SIGN:
                if char == ">":
                    parsed_result = _ParsedResult.Success
                else:
                    parsed_result = _ParsedResult.Failed

        return parsed_result

    def _generate_by_result(self, parsed_result: _ParsedResult) -> Generator[str | Tag, None, None]:
        if parsed_result == _ParsedResult.Success:
            assert self._tag is not None
            if self._is_tag_valid(self._tag):
                outside_text = self._outside_buffer.getvalue()
                self._clear_buffer(self._outside_buffer)
                self._clear_buffer(self._tag_buffer)
                if outside_text != "":
                    yield outside_text
                yield self._tag
            else:
                self._tag.proto = self._tag_buffer.getvalue()
                self._outside_buffer.write(self._tag.proto)
                self._clear_buffer(self._tag_buffer)
            self._tag = None
            self._phase = _Phase.OUTSIDE

        elif parsed_result == _ParsedResult.Failed:
            self._outside_buffer.write(self._tag_buffer.getvalue())
            self._clear_buffer(self._tag_buffer)
            self._phase = _Phase.OUTSIDE

    def _is_tag_valid(self, tag: Tag) -> bool:
        if tag.kind == TagKind.CLOSING and len(tag.attributes) > 0:
            return False
        if tag.find_invalid_name() is not None:
            return False
        return True

    def _clear_buffer(self, buffer: StringIO):
        buffer.truncate(0)
        buffer.seek(0)

from collections.abc import Generator
from dataclasses import dataclass
from enum import Enum, auto
from io import StringIO


class TagKind(Enum):
    OPENING = auto()
    CLOSING = auto()
    SELF_CLOSING = auto()


@dataclass
class Tag:
    kind: TagKind
    name: str
    proto: str
    attributes: list[tuple[str, str]]

    def __str__(self):
        buffer = StringIO()
        buffer.write("<")
        if self.kind == TagKind.CLOSING:
            buffer.write("/")
        buffer.write(self.name)
        if len(self.attributes) > 0:
            buffer.write(" ")
            for i, (attr_name, attr_value) in enumerate(self.attributes):
                buffer.write(attr_name)
                buffer.write("=")
                buffer.write('"')
                buffer.write(attr_value)
                buffer.write('"')
                if i < len(self.attributes) - 1:
                    buffer.write(" ")
        if self.kind == TagKind.SELF_CLOSING:
            buffer.write("/>")
        else:
            buffer.write(">")
        return buffer.getvalue()

    def find_invalid_name(self) -> str | None:
        for name in self._iter_tag_names():
            if not all(is_valid_value_char(c) for c in name):
                return name
            # https://www.w3schools.com/xml/xml_elements.asp
            # The following logic enforces a subset of XML naming rules:
            # - Names must not be empty.
            # - Names must start with a letter (a-z, A-Z) or an underscore (_).
            if name == "":
                return name
            char = name[0]
            if char == "_":
                continue
            if "a" <= char <= "z" or "A" <= char <= "Z":
                continue
            return name

        return None

    def find_invalid_attr_value(self) -> tuple[str, str] | None:
        for attr_name, attr_value in self.attributes:
            if not all(is_valid_value_char(c) for c in attr_value):
                return attr_name, attr_value
        return None

    def _iter_tag_names(self) -> Generator[str, None, None]:
        yield self.name
        for attr_name, _ in self.attributes:
            yield attr_name


# XML Attribute Values: https://www.w3.org/TR/xml/#NT-AttValue
# URI Syntax: https://www.rfc-editor.org/rfc/rfc3986
# HTML Attributes: https://html.spec.whatwg.org/multipage/syntax.html#attributes-2
_VALID_VALUE_CHARS = frozenset(
    (
        ",",
        ".",
        "/",
        "#",
        "?",
        "&",
        "=",
        ":",
        "%",
        ";",
        " ",
    )
)


# XML Names: https://www.w3.org/TR/xml/#NT-Name
# XML Namespaces: https://www.w3.org/TR/xml-names/#ns-qualnames
# HTML Custom Data Attributes: https://html.spec.whatwg.org/multipage/dom.html#custom-data-attribute
_VALID_NAME_CHARS = frozenset(("-", "_", ":", "."))


def is_valid_value_char(char: str) -> bool:
    if is_valid_name_char(char):
        return True
    if char in _VALID_VALUE_CHARS:
        return True
    return False


def is_valid_name_char(char: str) -> bool:
    if char in _VALID_NAME_CHARS:
        return True

    # https://www.w3.org/TR/xml/#NT-Name
    if "a" <= char <= "z":
        return True
    if "A" <= char <= "Z":
        return True
    if "0" <= char <= "9":
        return True
    return False

